def check_m(m):
    # 1. Check if T is an integer
    numerator = m * (m + 1)
    if numerator % 6 != 0:
        return False

    T = numerator // 6

    # T must be positive, which is true for m >= 3 (m=1, 2 result in non-integers or T=1 which we check below)
    if T == 0: 
        return False 

    S = list(range(1, m + 1))

    # --- Backtracking to find a suitable X ---

    def find_X_and_Y(index, current_sum, current_X):
        """
        Searches for a subset X summing to T. If found, checks if the remainder S' 
        contains a subset Y summing to T.
        """
        if current_sum == T:
            # Found potential X. Check if Y exists in S \ X.
            X = set(current_X)
            S_prime = [i for i in S if i not in X]

            if not S_prime:
                return False # X used up all elements

            # Check subset sum T in S_prime using DP
            # reachable_sums[j] is True if sum j is achievable using S_prime
            reachable_sums = {0}
            for item in S_prime:
                new_sums = set()
                for s in reachable_sums:
                    new_sum = s + item
                    if new_sum <= T:
                        new_sums.add(new_sum)
                reachable_sums.update(new_sums)

            if T in reachable_sums:
                # X and Y both exist and are non-empty (since T > 0)
                return True
            return False # Y does not exist

        if index >= m or current_sum > T:
            return False

        # Optimization: Pruning if remaining elements are too small/large
        remaining_sum = sum(S[index:])
        if current_sum + remaining_sum < T:
             return False # Cannot reach T even if all remaining elements are used

        # Option 1: Include S[index] in X
        if find_X_and_Y(index + 1, current_sum + S[index], current_X + [S[index]]):
            return True

        # Option 2: Exclude S[index] from X
        # We must ensure that excluding S[index] still allows T to be reached by a subset of S[index+1:]
        # This check is implicit in the full backtracking exploration.
        if find_X_and_Y(index + 1, current_sum, current_X):
            return True

        return False

    # Handle small cases where T might be small or search might be complex
    if T == 1: # m=2. S={1, 2}. T=1. X={1}. S'={2}. T not in reachable sums of S'. Fails.
        return False

    return find_X_and_Y(0, 0, [])


count = 0
for m in range(1, 101):
    if check_m(m):
        count += 1

print(f"Total count found: {count}")

def solve_partition(n, target_sum):
    """
    Checks if the set {1, 2, ..., n} can be partitioned into three subsets 
    each summing to target_sum.
    We are looking for three disjoint subsets X, Y, Z such that S(X)=S(Y)=S(Z)=target_sum.
    """

    elements = list(range(1, n + 1))

    # Using a backtracking approach for 3-way partition
    def backtrack(index, remaining_sums):
        if index == n:
            # Check if all sums are 0 (meaning we successfully placed all elements)
            return all(s == 0 for s in remaining_sums)

        element = elements[index]

        # Try putting the current element into one of the three bins
        for i in range(3):
            if remaining_sums[i] >= element:
                remaining_sums[i] -= element
                if backtrack(index + 1, remaining_sums):
                    return True
                remaining_sums[i] += element # Backtrack
        return False

    # Initial call: three bins, each needing to sum to target_sum
    return backtrack(0, [target_sum, target_sum, target_sum])

# Test cases requested
test_cases = {
    12: 26,
    14: 35,
    15: 40
}

results = {}
for m, S in test_cases.items():
    # Check total sum first
    total_sum = m * (m + 1) // 2
    if total_sum != 3 * S:
        results[m] = False # Should not happen given how S was calculated, but good practice
        continue

    results[m] = solve_partition(m, S)

print(results)
